_erf = np.vectorize(math.erf, otypes=[float])


def _sigmoid(x):
    return 0.5 * (1.0 + np.tanh(0.5 * x))


PRESETS = {
    "sigmoid": _sigmoid,
    "tanh": np.tanh,
    "gelu": lambda x: 0.5 * x * (1.0 + _erf(x / math.sqrt(2.0))),
    "relu": lambda x: np.maximum(x, 0.0),
    "sign": lambda x: np.sign(x),
    "step": lambda x: (np.asarray(x, dtype=float) > 0).astype(float),
    "inv": lambda x: 1.0 / x,
    "rsqrt": lambda x: 1.0 / np.sqrt(x),
    "exp": np.exp,
    "log": np.log,
    "softplus": lambda x: np.logaddexp(0.0, x),
    "silu": lambda x: x * _sigmoid(x),
}

GAP_FUNCS = {"sign", "step"}          # fitted and graded outside |x| < eps
COMPOSITE_FUNCS = {"sign", "step", "relu"}
POSITIVE_DOMAIN_FUNCS = {"inv", "rsqrt", "log"}

SERIES_METHODS = ("interp", "ls", "wls", "minimax")


def make_expr_function(expr):
    """Compile `--expr` into a numpy function of x (restricted namespace)."""
    ns = {"np": np, "numpy": np, "pi": math.pi, "e": math.e, "erf": _erf,
          "sigmoid": _sigmoid}
    for name in ("exp", "log", "log1p", "sqrt", "abs", "tanh", "sinh", "cosh",
                 "sin", "cos", "tan", "arctan", "where", "maximum", "minimum",
                 "sign", "clip", "logaddexp", "power", "square", "cbrt"):
        ns[name] = getattr(np, name)
    code = compile(expr, "<expr>", "eval")

    def f(x):
        x = np.asarray(x, dtype=float)
        return np.broadcast_to(np.asarray(eval(code, {"__builtins__": {}},
                                               dict(ns, x=x)), dtype=float),
                               x.shape).copy()
    return f


# ---------------------------------------------------------------------------
# Depth, basis and evaluation helpers
# ---------------------------------------------------------------------------

# OpenFHE's Paterson-Stockmeyer table degrees; measured with fhe-cheb-lab, the
# level cost steps up exactly after each entry (see "Depth accounting" above).
PS_TABLE = [5, 13, 27, 59, 119, 247, 495, 1007, 2031]


def depth_of_degree(d):
    """Levels a degree-d Chebyshev series consumes (measured, OpenFHE 1.5.1)."""
    for i, top in enumerate(PS_TABLE):
        if d <= top:
            return i + 4
    return len(PS_TABLE) + 4 + int(math.ceil(math.log2((d + 1) / (PS_TABLE[-1] + 1))))


def max_degree_for_depth(D):
    """Largest degree that fits in D levels: the table entry at D."""
    if D < 4:
        return 1
    if D - 4 < len(PS_TABLE):
        return PS_TABLE[D - 4]
    return 2 ** (D - 1) - 1


def to_t(x, a, b):
    return (2.0 * np.asarray(x, dtype=float) - a - b) / (b - a)


def openfhe_to_std(c):
    """OpenFHE vector (c_0 stored at 2x) -> ordinary Chebyshev coefficients."""
    a = np.array(c, dtype=float)
    a[0] *= 0.5
    return a


def std_to_openfhe(a):
    c = np.array(a, dtype=float)
    c[0] *= 2.0
    return c


def clenshaw_openfhe(coeffs, x, a, b):
    """Evaluate c_0/2 + sum_k c_k T_k(t) by Clenshaw recurrence."""
    t = to_t(x, a, b)
    b1 = np.zeros_like(t)
    b2 = np.zeros_like(t)
    for k in range(len(coeffs) - 1, 0, -1):
        b1, b2 = 2.0 * t * b1 - b2 + coeffs[k], b1
    return t * b1 - b2 + 0.5 * coeffs[0]


def coef_norms(coeffs):
    w = np.abs(np.asarray(coeffs, dtype=float))
    w[0] *= 0.5
    return float(w.sum()), float(w.max())


def parity_indices(degree, parity):
    ks = np.arange(degree + 1)
    if parity == "odd":
        return ks[ks % 2 == 1]
    if parity == "even":
        return ks[ks % 2 == 0]
    return ks


# ---------------------------------------------------------------------------
# Fitting methods
# ---------------------------------------------------------------------------

def interp_coeffs(f, a, b, degree):
    """Vectorised transcription of OpenFHE's EvalChebyshevCoefficients."""
    n = degree + 1
    theta = math.pi * (np.arange(n) + 0.5) / n
    x = np.cos(theta) * (0.5 * (b - a)) + 0.5 * (b + a)
    fx = np.asarray(f(x), dtype=float)
    M = np.cos(np.outer(np.arange(n), theta))
    return (2.0 / n) * (M @ fx)


def interp_coeffs_reference(func, a, b, degree):
    """Literal (scalar loop) transcription of the OpenFHE C++ for --selftest."""
    coeffTotal = degree + 1
    bMinusA = 0.5 * (b - a)
    bPlusA = 0.5 * (b + a)
    PiByDeg = math.pi / float(coeffTotal)
    functionPoints = [float(func(math.cos(PiByDeg * (i + 0.5)) * bMinusA + bPlusA))
                      for i in range(coeffTotal)]
    multFactor = 2.0 / float(coeffTotal)
    coefficients = []
    for i in range(coeffTotal):
        s = 0.0
        for j in range(coeffTotal):
            s += functionPoints[j] * math.cos(PiByDeg * i * (j + 0.5))
        coefficients.append(s * multFactor)
    return coefficients


def make_grid(kind, n, a, b, parity, gap_eps):
    """Chebyshev-distributed grid in x (and t).  kind: 'nodes' (first kind,
    interior) or 'extrema' (second kind, includes the endpoints).  With a
    parity only the half t >= 0 is returned; with a gap |x| < gap_eps is
    dropped."""
    if kind == "nodes":
        t = np.cos(math.pi * (np.arange(n) + 0.5) / n)
    else:
        # Chebyshev extrema (dense at the ends) + a uniform grid (dense in the
        # middle, where kinks and gap edges live) + the gap edges themselves.
        t = np.concatenate([np.cos(math.pi * np.arange(n) / (n - 1)),
                            np.linspace(-1.0, 1.0, n)])
        if gap_eps:
            t = np.concatenate([t, to_t(np.array([-gap_eps, gap_eps]), a, b)])
        t = np.unique(t)
    if parity:
        t = t[t >= 0.0]
    x = t * (0.5 * (b - a)) + 0.5 * (b + a)
    if gap_eps:
        keep = np.abs(x) >= gap_eps * (1.0 - 1e-12)
        x, t = x[keep], t[keep]
    return x, t


def weighted_lstsq(V, y, w):
    """One-shot weighted least squares (SVD based, maximal accuracy)."""
    sw = np.sqrt(w)
    return np.linalg.lstsq(sw[:, None] * V, sw * y, rcond=None)[0]


def weighted_lstsq_fast(V, y, w):
    """Weighted least squares via the normal equations on the active points
    (w > 1e-30*max), the inner step of Lawson; the Chebyshev basis on a
    Chebyshev-distributed grid has condition ~4, so squaring it is harmless.
    Falls back to the SVD solve if the normal matrix is singular."""
    act = w > 1e-30 * w.max()
    if not act.all():
        V, y, w = V[act], y[act], w[act]
    sw = np.sqrt(w)
    B = sw[:, None] * V
    g = sw * y
    try:
        c = np.linalg.solve(B.T @ B, B.T @ g)
        if np.all(np.isfinite(c)):
            return c
    except np.linalg.LinAlgError:
        pass
    return np.linalg.lstsq(B, g, rcond=None)[0]


def equioscillation_count(e, rel=1e-3):
    """Number of alternating-sign clusters of |error| within rel of the max."""
    emax = np.max(np.abs(e))
    if emax == 0.0:
        return 0
    idx = np.flatnonzero(np.abs(e) >= (1.0 - rel) * emax)
    s = np.sign(e[idx])
    return int(1 + np.count_nonzero(s[1:] != s[:-1]))


def local_maxima(ae):
    left = np.r_[True, ae[1:] >= ae[:-1]]
    right = np.r_[ae[:-1] >= ae[1:], True]
    return np.flatnonzero(left & right & (ae > 0.0))


def alternating_extrema(e):
    """One index per sign run of e (the largest |e| in the run), in grid
    order, so the signs alternate.  Zeros of e join the preceding run."""
    s = np.sign(e)
    nz = np.flatnonzero(s)
    if nz.size == 0:
        return []
    filled = s[np.maximum.accumulate(np.where(s != 0, np.arange(len(s)), 0))]
    filled[:nz[0]] = s[nz[0]]
    breaks = np.flatnonzero(filled[1:] != filled[:-1]) + 1
    starts = np.r_[0, breaks]
    ends = np.r_[breaks, len(e)]
    ae = np.abs(e)
    return [int(st + np.argmax(ae[st:en])) for st, en in zip(starts, ends)]


def trim_reference(ref, ae, m1):
    """Reduce an alternating index list to m1 entries, keeping alternation."""
    ref = list(ref)
    while len(ref) > m1:
        if len(ref) - m1 == 1:
            ref.pop(0 if ae[ref[0]] < ae[ref[-1]] else -1)
        else:
            pair = min(range(len(ref) - 1),
                       key=lambda i: max(ae[ref[i]], ae[ref[i + 1]]))
            del ref[pair:pair + 2]
    return ref


def exchange_polish(V, y, c0, max_iter=60, tol=1e-13):
    """Discrete Remez (multiple exchange) steps on the grid, seeded with the
    alternating extrema of the error of c0.  Returns (best coeffs, best max
    error, best levelled error h, iterations).  By de la Vallee Poussin, h
    from any alternating reference of m+1 points is a lower bound on the grid
    minimax error, so (emax - h)/emax certifies optimality."""
    m = V.shape[1]
    m1 = m + 1
    e = y - V @ c0
    ae = np.abs(e)
    best_c, best_emax = c0, float(ae.max())
    h_best = 0.0
    ref = alternating_extrema(e)
    if len(ref) >= m1:
        ref = trim_reference(ref, ae, m1)
    else:
        # Too few alternations in the seed (an unconverged Lawson iterate can
        # hide an extremum): seed with the m+1 largest local maxima of |e| in
        # grid order.  The levelled solve then forces m+1 alternations into
        # its own error, so the next reference is a proper one.
        cand = local_maxima(ae)
        if len(cand) < m1:
            cand = np.arange(len(e))
        ref = sorted(cand[np.argsort(ae[cand])[::-1][:m1]].tolist())
    signs = np.where(np.arange(m1) % 2 == 0, 1.0, -1.0)
    it = 0
    for it in range(1, max_iter + 1):
        if len(ref) < m1 or len(set(ref)) < m1:
            break
        A = np.empty((m1, m1))
        A[:, :m] = V[ref]
        A[:, m] = signs
        try:
            sol = np.linalg.solve(A, y[ref])
        except np.linalg.LinAlgError:
            break
        if not np.all(np.isfinite(sol)):
            break
        c, h = sol[:m], abs(float(sol[m]))
        e = y - V @ c
        emax = float(np.max(np.abs(e)))
        h_best = max(h_best, h)
        if emax < best_emax:
            best_c, best_emax = c, emax
        if emax - h <= tol * emax:
            break
        new_ref = trim_reference(alternating_extrema(e), np.abs(e), m1)
        if new_ref == ref:
            break
        ref = new_ref
    return best_c, best_emax, h_best, it


def lawson_minimax(V, y, w0, max_iter=500, tol=1e-12, polish=True, handoff=1e-2):
    """Discrete minimax polynomial on the grid: Lawson IRLS (w <- w*|e|/sum
    w|e|), which converges linearly to the minimax polynomial on the grid,
    followed by Remez exchange steps seeded from Lawson's extremal set, which
    tighten the result to the grid optimum.  Lawson stops when the max error
    changes by < tol relative, when its duality gap is < tol, after max_iter
    iterations, or (with polish) once the gap is < handoff; if the exchange
    then fails to certify, Lawson resumes to max_iter and the exchange runs
    again.  Returns (coeffs, info); coeffs is the best iterate seen, info
    carries the certificate (duality_gap)."""
    st = {"w": np.array(w0, dtype=float) / float(np.sum(w0)), "best_c": None,
          "best_emax": np.inf, "prev_emax": np.inf, "lower": 0.0, "it": 0}

    def run_lawson(n_iter, stop_gap):
        w = st["w"]
        for _ in range(n_iter):
            st["it"] += 1
            c = weighted_lstsq_fast(V, y, w)
            e = y - V @ c
            ae = np.abs(e)
            emax = float(ae.max())
            st["lower"] = max(st["lower"], float(np.dot(w, ae)))   # Lawson's bound
            if emax < st["best_emax"]:
                st["best_c"], st["best_emax"] = c, emax
            if (abs(emax - st["prev_emax"]) <= tol * emax
                    or st["best_emax"] - st["lower"] <= max(tol, stop_gap) * st["best_emax"]):
                break
            st["prev_emax"] = emax
            w = w * ae
            total = w.sum()
            if total <= 0.0:
                break
            w = w / total
            st["w"] = w

    def run_polish():
        pc, pemax, h, n = exchange_polish(V, y, st["best_c"])
        st["lower"] = max(st["lower"], h)
        if pemax < st["best_emax"]:
            st["best_c"], st["best_emax"] = pc, pemax
        return n

    def gap_now():
        return (max(0.0, (st["best_emax"] - st["lower"]) / st["best_emax"])
                if st["best_emax"] > 0 else 0.0)

    run_lawson(max_iter, handoff if polish else 0.0)
    xit = 0
    if polish and st["best_emax"] > 0.0:
        xit = run_polish()
        if gap_now() > 1e-8 and st["it"] < max_iter:
            run_lawson(max_iter - st["it"], 0.0)
            xit += run_polish()
    best_c, best_emax, it = st["best_c"], st["best_emax"], st["it"]
    gap = gap_now()
    e = y - V @ best_c
    info = {"iterations": it, "exchange_iterations": xit, "duality_gap": float(gap),
            "grid_max_err": float(best_emax),
            "roundoff": bool(best_emax <= 1e-13 * max(1.0, float(np.max(np.abs(y))))),
            "equioscillation": equioscillation_count(e, rel=min(1e-2, max(1e-9, 10.0 * gap)))}
    return best_c, info


def fit_series(method, f, a, b, degree, parity, gap_eps, density, args):
    """Return (openfhe_coeffs, note_dict) for one series method."""
    note = {}
    if method == "interp":
        c = interp_coeffs(f, a, b, degree)
        if parity:
            keep = np.zeros(degree + 1, dtype=bool)
            keep[parity_indices(degree, parity)] = True
            c[~keep] = 0.0
        return c, note

    ks = parity_indices(degree, parity)
    if method in ("ls", "wls"):
        n = max(20 * degree, 4 * (degree + 1))
        x, t = make_grid("nodes", n, a, b, parity, gap_eps)
    else:
        n = max(args.minimax_grid, 16 * (degree + 1))
        x, t = make_grid("extrema", n, a, b, parity, gap_eps)
    V = npcheb.chebvander(t, degree)[:, ks]
    y = np.asarray(f(x), dtype=float)

    if method == "wls" and density is None:
        note["fallback"] = "wls->ls (no --samples)"
        method_eff = "ls"
    else:
        method_eff = method

    if method_eff == "wls":
        w = density(x)
        if parity:
            w = w + density(-x)
        w = w * np.sqrt(np.maximum(1.0 - t * t, 0.0))
        w = w + 1e-6 * w.max()
        if w.max() <= 0:
            w = np.ones_like(x)
    else:
        w = np.ones_like(x)

    if method_eff in ("ls", "wls"):
        cs = weighted_lstsq(V, y, w)
    else:
        cs, info = lawson_minimax(V, y, w, max_iter=args.max_iter, tol=args.tol,
                                  polish=not args.no_polish, handoff=args.handoff)
        info["expected_equioscillation"] = int(len(ks) + 1)
        note.update(info)

    full = np.zeros(degree + 1)
    full[ks] = cs
    return std_to_openfhe(full), note


# ---------------------------------------------------------------------------
# Composite (CKK) sign
# ---------------------------------------------------------------------------

CKK_POWER_COEFFS = [0.0, 35.0 / 16, 0.0, -35.0 / 16, 0.0, 21.0 / 16, 0.0, -5.0 / 16]


def ckk_f(x):
    x2 = x * x
    return x * (35.0 + x2 * (-35.0 + x2 * (21.0 - 5.0 * x2))) / 16.0


def composite_sign(x, k):
    y = np.asarray(x, dtype=float)
    for _ in range(k):
        y = ckk_f(y)
    return y


def composite_function(name, k, scale):
    """Approximation of sign/step/relu built from k CKK stages on x/scale."""
    if name == "sign":
        return lambda x: composite_sign(np.asarray(x, float) / scale, k)
    if name == "step":
        return lambda x: 0.5 * (1.0 + composite_sign(np.asarray(x, float) / scale, k))
    return lambda x: np.asarray(x, float) * 0.5 * (
        1.0 + composite_sign(np.asarray(x, float) / scale, k))


def composite_depth(name, k):
    return depth_of_degree(7) * k + (1 if name == "relu" else 0)


# ---------------------------------------------------------------------------
# Samples and density
# ---------------------------------------------------------------------------

class Density:
    def __init__(self, samples, a, b, bins=512):
        samples = np.asarray(samples, dtype=float).ravel()
        samples = samples[np.isfinite(samples)]
        self.total = samples.size
        inside = samples[(samples >= a) & (samples <= b)]
        self.n_outside = self.total - inside.size
        self.inside = inside
        self.hist, self.edges = np.histogram(inside, bins=bins, range=(a, b),
                                             density=True)
        self.p_lo, self.p_hi = (np.percentile(samples, [0.1, 99.9])
                                if samples.size else (np.nan, np.nan))

    def __call__(self, x):
        idx = np.searchsorted(self.edges, np.asarray(x, float), side="right") - 1
        idx = np.clip(idx, 0, len(self.hist) - 1)
        return self.hist[idx]


def load_samples(path):
    if path.endswith(".npy"):
        s = np.load(path, allow_pickle=False)
    else:
        s = np.loadtxt(path)
    return np.asarray(s, dtype=float).ravel()


# ---------------------------------------------------------------------------
# Metrics
# ---------------------------------------------------------------------------

def error_metrics(approx, f, eval_x, sample_x):
    e = np.asarray(approx(eval_x), float) - np.asarray(f(eval_x), float)
    m = {"max_err": float(np.max(np.abs(e))),
         "rms_err": float(np.sqrt(np.mean(e * e)))}
    if sample_x is not None and sample_x.size:
        es = np.abs(np.asarray(approx(sample_x), float) - np.asarray(f(sample_x), float))
        m["smp_max"] = float(es.max())
        m["smp_mean"] = float(es.mean())
        m["smp_p999"] = float(np.percentile(es, 99.9))
    return m


def detect_symmetry(f, a, b):
    if abs(a + b) > 1e-12 * (b - a):
        return None
    x = np.linspace(0.0, b, 257)[1:]
    fp, fm = np.asarray(f(x), float), np.asarray(f(-x), float)
    scale = max(1.0, float(np.max(np.abs(fp))))
    if np.max(np.abs(fp + fm)) <= 1e-9 * scale:
        return "odd"
    if np.max(np.abs(fp - fm)) <= 1e-9 * scale:
        return "even"
    return None


# ---------------------------------------------------------------------------
# Reporting
# ---------------------------------------------------------------------------

def fmt(v):
    if v is None or (isinstance(v, float) and not np.isfinite(v)):
        return "-"
    if isinstance(v, str):
        return v
    return "%.3e" % v


def print_table(rows, have_samples):
    cols = ["method", "degree", "depth", "max_err", "rms_err"]
    if have_samples:
        cols += ["smp_max", "smp_mean", "smp_p999"]
    cols += ["coef_l1", "coef_max", "notes"]
    lines = ["| " + " | ".join(cols) + " |", "|" + "|".join("---" for _ in cols) + "|"]
    for r in rows:
        cells = [str(r.get("method", "")), str(r.get("degree", "")), str(r.get("depth", ""))]
        cells += [fmt(r.get("max_err")), fmt(r.get("rms_err"))]
        if have_samples:
            cells += [fmt(r.get("smp_max")), fmt(r.get("smp_mean")), fmt(r.get("smp_p999"))]
        cells += [fmt(r.get("coef_l1")), fmt(r.get("coef_max")), r.get("notes", "")]
        lines.append("| " + " | ".join(cells) + " |")
    print("\n".join(lines))


def note_string(note):
    parts = []
    if "fallback" in note:
        parts.append(note["fallback"])
    if "iterations" in note:
        parts.append("lawson it=%d exch=%d gap=%.1e equiosc=%d/%d%s" % (
            note["iterations"], note["exchange_iterations"], note["duality_gap"],
            note["equioscillation"], note["expected_equioscillation"],
            " (error at roundoff)" if note.get("roundoff") else ""))
    for k in ("parity", "gap_excl_max", "comment"):
        if k in note:
            parts.append(note[k] if isinstance(note[k], str) else "%s=%.3e" % (k, note[k]))
    return "; ".join(parts)


TWIN_TEMPLATE = '''# Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
# Faithful-twin evaluation of OpenFHE EvalChebyshevSeries(ct, COEFFS, A, B)
# for target "{func}" fitted by "{method}" (degree {degree}, depth {depth}).
# Convention: p(x) = COEFFS[0]/2 + sum_k COEFFS[k]*T_k(t), t = (2x-A-B)/(B-A).
import numpy as np

A, B = {a!r}, {b!r}
DEGREE = {degree}
COEFFS = np.array([
{coeffs}
])


def eval_cheb_series(x, coeffs=COEFFS, a=A, b=B):
    """Clenshaw evaluation of the OpenFHE-convention Chebyshev series."""
    x = np.asarray(x, dtype=float)
    t = (2.0 * x - a - b) / (b - a)
    b1 = np.zeros_like(t)
    b2 = np.zeros_like(t)
    for k in range(len(coeffs) - 1, 0, -1):
        b1, b2 = 2.0 * t * b1 - b2 + coeffs[k], b1
    return t * b1 - b2 + 0.5 * coeffs[0]
'''

TWIN_COMPOSITE_TEMPLATE = '''# Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
# Faithful-twin evaluation of the composite CKK approximation of "{func}":
# {k} stages of f(y) = (35y - 35y^3 + 21y^5 - 5y^7)/16 on y = x/{scale!r},
# total depth {depth} (4 per stage{extra}).
import numpy as np

K = {k}
SCALE = {scale!r}


def ckk_stage(y):
    y2 = y * y
    return y * (35.0 + y2 * (-35.0 + y2 * (21.0 - 5.0 * y2))) / 16.0


def eval_composite(x):
    x = np.asarray(x, dtype=float)
    s = x / SCALE
    for _ in range(K):
        s = ckk_stage(s)
    return {final}
'''


def write_twin(path, func_name, method, coeffs, a, b, degree, composite=None):
    if composite is not None:
        k, scale = composite
        final = {"sign": "s", "step": "0.5 * (1.0 + s)", "relu": "x * 0.5 * (1.0 + s)"}[func_name]
        text = TWIN_COMPOSITE_TEMPLATE.format(
            func=func_name, k=k, scale=float(scale), depth=composite_depth(func_name, k),
            extra=" + 1 for x*(.)" if func_name == "relu" else "", final=final)
    else:
        body = ",\n".join("    " + ", ".join("%.17g" % v for v in coeffs[i:i + 4])
                          for i in range(0, len(coeffs), 4))
        text = TWIN_TEMPLATE.format(func=func_name, method=method, degree=degree,
                                    depth=depth_of_degree(degree), a=float(a),
                                    b=float(b), coeffs=body)
    with open(path, "w") as fh:
        fh.write(text)


# ---------------------------------------------------------------------------
# Main fitting driver
# ---------------------------------------------------------------------------

def run(args):
    t0 = time.time()
    if args.expr:
        func_name, f = "expr", make_expr_function(args.expr)
    else:
        func_name, f = args.function, PRESETS[args.function]
    a, b = float(args.domain[0]), float(args.domain[1])
    if not b > a:
        sys.exit("error: domain must satisfy a < b")
    if func_name in POSITIVE_DOMAIN_FUNCS and a <= 0:
        sys.exit("error: %s needs a domain with a > 0" % func_name)

    if args.degree is not None:
        degree = args.degree
    else:
        degree = max_degree_for_depth(args.depth)
    if degree < 1:
        sys.exit("error: degree must be >= 1")
    depth = depth_of_degree(degree)

    gap_eps = args.eps if func_name in GAP_FUNCS else 0.0

    # symmetry
    parity, sym_note = None, "none"
    detected = detect_symmetry(f, a, b)
    if args.odd or args.even:
        parity = "odd" if args.odd else "even"
        sym_note = "%s (forced%s)" % (parity, "" if detected == parity
                                      else "; WARNING: target does not look %s on this domain" % parity)
    elif args.auto_symmetry:
        parity = detected
        sym_note = "%s (auto-detected)" % parity if parity else "none detected (full basis)"
    if parity:
        nterms = len(parity_indices(degree, parity))
        sym_note += ", %d %s terms of %d" % (nterms, parity, degree + 1)

    # samples
    density, sample_x = None, None
    sample_note = "none"
    if args.samples:
        s = load_samples(args.samples)
        density = Density(s, a, b, bins=args.bins)
        sample_x = density.inside
        if gap_eps:
            sample_x = sample_x[np.abs(sample_x) >= gap_eps]
        sample_note = ("%d loaded, %d outside the domain (excluded), p0.1/p99.9 = %.4g / %.4g"
                       % (density.total, density.n_outside, density.p_lo, density.p_hi))
        if gap_eps:
            sample_note += ", %d inside the gap (excluded)" % (density.inside.size - sample_x.size)

    # evaluation grid
    eval_x = np.linspace(a, b, args.eval_points)
    if gap_eps:
        eval_x = np.unique(np.concatenate([eval_x[np.abs(eval_x) >= gap_eps],
                                           [-gap_eps, gap_eps]]))

    print("# cheb_fit: %s on [%g, %g], degree %d (depth %d)" % (
        func_name if not args.expr else "expr %r" % args.expr, a, b, degree, depth))
    print("- symmetry: %s" % sym_note)
    print("- samples: %s" % sample_note)
    if gap_eps:
        print("- gap: fit grids and metrics exclude |x| < %g (discontinuous target)" % gap_eps)
    print("- coefficient convention: OpenFHE EvalChebyshevCoefficients (series = c0/2 + sum c_k T_k)")

    methods = [m.strip() for m in args.methods.split(",") if m.strip()]
    rows, results = [], {}
    for m in methods:
        if m not in SERIES_METHODS:
            sys.exit("error: unknown method %r (choose from %s)" % (m, ", ".join(SERIES_METHODS)))
        coeffs, note = fit_series(m, f, a, b, degree, parity, gap_eps, density, args)
        approx = lambda x, c=coeffs: clenshaw_openfhe(c, x, a, b)
        met = error_metrics(approx, f, eval_x, sample_x)
        l1, lmax = coef_norms(coeffs)
        if parity:
            note["parity"] = parity
        row = dict(method=m, degree=degree, depth=depth, coef_l1=l1, coef_max=lmax,
                   notes=note_string(note), **met)
        rows.append(row)
        results[m] = dict(coeffs=[float(v) for v in coeffs], a=a, b=b, degree=degree,
                          depth=depth, parity=parity, metrics=met, coef_l1=l1,
                          coef_max=lmax, notes=note)

    composites = []
    if func_name in COMPOSITE_FUNCS:
        scale = max(abs(a), abs(b))
        gap_x = eval_x[np.abs(eval_x) >= args.eps]
        for k in range(1, args.composite_k + 1):
            g = composite_function(func_name, k, scale)
            met = error_metrics(g, f, eval_x, sample_x)
            cd = composite_depth(func_name, k)
            note = {"comment": "CKK f composed %d times" % k}
            if func_name == "relu":
                note["gap_excl_max"] = float(np.max(np.abs(g(gap_x) - f(gap_x))))
            row = dict(method="composite k=%d" % k, degree="7%s" % ("o%d" % k if k > 1 else ""),
                       depth=cd, coef_l1=6.0, coef_max=35.0 / 16,
                       notes=note_string(note) + "; coef norms per stage, power basis", **met)
            rows.append(row)
            comp = dict(k=k, depth=cd, scale=scale, eps=args.eps,
                        stage_power_coeffs=CKK_POWER_COEFFS, metrics=met)
            # single-polynomial minimax at the same total depth
            dcmp = max_degree_for_depth(cd)
            if dcmp <= args.compare_cap:
                if dcmp == degree and "minimax" in results:
                    cc = np.array(results["minimax"]["coeffs"])
                    cnote = dict(results["minimax"]["notes"])
                else:
                    cc, cnote = fit_series("minimax", f, a, b, dcmp, parity, gap_eps, density, args)
                approx = lambda x, c=cc: clenshaw_openfhe(c, x, a, b)
                cmet = error_metrics(approx, f, eval_x, sample_x)
                cl1, cmax = coef_norms(cc)
                rows.append(dict(method="minimax @depth%d" % cd, degree=dcmp, depth=cd,
                                 coef_l1=cl1, coef_max=cmax, notes=note_string(cnote), **cmet))
                comp["minimax_same_depth"] = dict(coeffs=[float(v) for v in cc], a=a, b=b,
                                                  degree=dcmp, depth=cd, metrics=cmet,
                                                  coef_l1=cl1, coef_max=cmax, notes=cnote)
            else:
                rows.append(dict(method="minimax @depth%d" % cd, degree=dcmp, depth=cd,
                                 notes="not fitted: degree > --compare-cap %d" % args.compare_cap))
            composites.append(comp)

    print()
    print_table(rows, sample_x is not None)
    print()
    nmm = max(args.minimax_grid, 16 * (degree + 1))
    print("- eval grid: %d uniform points; minimax grid: %d Chebyshev-extrema + %d uniform points; "
          "elapsed %.1f s" % (args.eval_points, nmm, nmm, time.time() - t0))

    if args.json:
        out = dict(function=func_name, expr=args.expr, a=a, b=b, degree=degree, depth=depth,
                   parity=parity, eps=args.eps if func_name in COMPOSITE_FUNCS else None,
                   convention="OpenFHE EvalChebyshevCoefficients: p(x)=c0/2+sum_{k>=1} c_k T_k(t), "
                              "t=(2x-a-b)/(b-a); depth from OpenFHE's PS table (5,13,27,59,119,247,...: measured)",
                   samples=dict(path=args.samples, note=sample_note) if args.samples else None,
                   methods=results, composite=composites)
        with open(args.json, "w") as fh:
            json.dump(out, fh, indent=1)
        print("- wrote %s" % args.json)

    if args.twin:
        emit = args.emit or ("interp" if "interp" in results else methods[0])
        if emit.startswith("composite"):
            if func_name not in COMPOSITE_FUNCS:
                sys.exit("error: composite emission is only for sign/step/relu")
            k = int(emit.split(":")[1]) if ":" in emit else 1
            write_twin(args.twin, func_name, emit, None, a, b, degree,
                       composite=(k, max(abs(a), abs(b))))
        else:
            if emit not in results:
                sys.exit("error: --emit %r is not among the fitted methods" % emit)
            write_twin(args.twin, func_name, emit, results[emit]["coeffs"], a, b, degree)
        print("- wrote %s (%s)" % (args.twin, emit))
    return rows, results


# ---------------------------------------------------------------------------
# Self test
# ---------------------------------------------------------------------------

def selftest(args):
    failures = []

    def check(name, ok, detail):
        print("%s %s: %s" % ("PASS" if ok else "FAIL", name, detail))
        if not ok:
            failures.append(name)

    # (a) interp matches the literal OpenFHE loop
    f = PRESETS["sigmoid"]
    c_vec = interp_coeffs(f, -8.0, 8.0, 27)
    c_ref = np.array(interp_coeffs_reference(f, -8.0, 8.0, 27))
    d = float(np.max(np.abs(c_vec - c_ref)))
    check("interp matches OpenFHE loop (sigmoid [-8,8] deg 27)", d < 1e-12, "max diff %.2e" % d)

    # (b) Clenshaw equals numpy evaluation of the same series
    x = np.linspace(-8.0, 8.0, 1001)
    t = to_t(x, -8.0, 8.0)
    y_cl = clenshaw_openfhe(c_vec, x, -8.0, 8.0)
    y_np = npcheb.chebval(t, openfhe_to_std(c_vec))
    d1 = float(np.max(np.abs(y_cl - y_np)))
    y_pw = np.polynomial.polynomial.polyval(t, npcheb.cheb2poly(openfhe_to_std(c_vec)))
    d2 = float(np.max(np.abs(y_cl - y_pw)))
    check("Clenshaw == numpy chebval", d1 < 1e-12, "max diff %.2e" % d1)
    check("Clenshaw == power-basis polyval", d2 < 1e-6, "max diff %.2e (cheb2poly cancellation)" % d2)

    # (c) Lawson on |x| degree 10
    class A:
        minimax_grid, max_iter, tol, no_polish, handoff = 4096, 500, 1e-12, False, 1e-2
    cabs, note = fit_series("minimax", np.abs, -1.0, 1.0, 10, None, 0.0, None, A)
    xe = np.linspace(-1, 1, 200001)
    err = float(np.max(np.abs(clenshaw_openfhe(cabs, xe, -1, 1) - np.abs(xe))))
    # Best uniform approximation of |x| by degree-10 polynomials on [-1,1]
    # (Varga-Carpenter; 2n*E_2n -> Bernstein's constant 0.2801694...).
    ref = 0.02781
    check("Lawson |x| deg 10 max error ~ E_10", abs(err - ref) / ref < 0.02,
          "max err %.6f vs E_10 ~ %.5f (grid gap %.1e, %d lawson + %d exchange iters, "
          "equiosc %d/%d)" % (err, ref, note["duality_gap"], note["iterations"],
                              note["exchange_iterations"], note["equioscillation"],
                              note["expected_equioscillation"]))
    check("Lawson equioscillation count", note["equioscillation"] >= 12,
          "%d alternations (need >= 12)" % note["equioscillation"])
    A.no_polish = True
    cabs2, note2 = fit_series("minimax", np.abs, -1.0, 1.0, 10, None, 0.0, None, A)
    err2 = float(np.max(np.abs(clenshaw_openfhe(cabs2, xe, -1, 1) - np.abs(xe))))
    check("pure Lawson (no polish) |x| deg 10", abs(err2 - ref) / ref < 0.02,
          "max err %.6f (gap %.1e after %d iters); polish improves the grid max err by %.1e" % (
              err2, note2["duality_gap"], note2["iterations"],
              note2["grid_max_err"] - note["grid_max_err"]))
    A.no_polish = False

    # (d) odd-symmetry path == full fit for tanh
    class B:
        minimax_grid, max_iter, tol, no_polish, handoff = 4096, 500, 1e-12, False, 1e-2
    for m, tol in (("interp", 1e-10), ("ls", 1e-8), ("minimax", 1e-5)):
        cf, _ = fit_series(m, np.tanh, -4.0, 4.0, 15, None, 0.0, None, B)
        co, _ = fit_series(m, np.tanh, -4.0, 4.0, 15, "odd", 0.0, None, B)
        xe = np.linspace(-4, 4, 8192)
        ef = float(np.max(np.abs(clenshaw_openfhe(cf, xe, -4, 4) - np.tanh(xe))))
        eo = float(np.max(np.abs(clenshaw_openfhe(co, xe, -4, 4) - np.tanh(xe))))
        even_mass = float(np.max(np.abs(cf[0::2])))
        check("odd path == full fit for tanh (%s)" % m, abs(ef - eo) <= tol * ef,
              "full %.6e odd %.6e (rel diff %.1e; even coeffs in full fit <= %.1e)" % (
                  ef, eo, abs(ef - eo) / ef, even_mass))

    # depth bookkeeping
    check("depth table", [depth_of_degree(d) for d in (5, 6, 13, 14, 27, 28, 59, 60, 119, 120, 247, 248)]
          == [4, 5, 5, 6, 6, 7, 7, 8, 8, 9, 9, 10] and max_degree_for_depth(6) == 27
          and max_degree_for_depth(8) == 119,
          "measured PS table: 5->4, 13->5, 27->6, 59->7, 119->8, 247->9; depth 6 -> degree 27")
    ck = CKK_POWER_COEFFS
    xx = np.linspace(-1, 1, 101)
    check("CKK polynomial", float(np.max(np.abs(np.polynomial.polynomial.polyval(xx, ck)
                                                 - ckk_f(xx)))) < 1e-15 and abs(ckk_f(1.0) - 1.0) < 1e-15,
          "f(1)=1, Horner matches power form")

    if failures:
        print("SELFTEST FAILED: %s" % ", ".join(failures))
        return 1
    print("SELFTEST PASSED")
    return 0


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def build_parser():
    p = argparse.ArgumentParser(
        prog="cheb_fit.py",
        description="Fit and compare polynomial approximations for CKKS "
                    "(OpenFHE EvalChebyshevSeries coefficient convention).",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="presets: " + ", ".join(PRESETS))
    p.add_argument("function", nargs="?", choices=sorted(PRESETS),
                   help="preset target function (or use --expr)")
    p.add_argument("--expr", help='numpy expression in x, e.g. "np.exp(-x*x)"')
    p.add_argument("--domain", nargs=2, type=float, metavar=("A", "B"), default=(-1.0, 1.0),
                   help="approximation interval [A, B] (default -1 1)")
    g = p.add_mutually_exclusive_group()
    g.add_argument("--degree", type=int, help="polynomial degree")
    g.add_argument("--depth", type=int, help="depth budget; uses degree 2^(D-1)-1")
    s = p.add_mutually_exclusive_group()
    s.add_argument("--odd", action="store_true", help="fit only odd Chebyshev terms")
    s.add_argument("--even", action="store_true", help="fit only even Chebyshev terms")
    s.add_argument("--auto-symmetry", action="store_true",
                   help="detect odd/even symmetry on the domain and exploit it")
    p.add_argument("--samples", help="operand samples: text (one float per line) or .npy")
    p.add_argument("--bins", type=int, default=512, help="histogram bins for the density")
    p.add_argument("--methods", default=",".join(SERIES_METHODS),
                   help="comma list of %s (default all)" % "/".join(SERIES_METHODS))
    p.add_argument("--eps", type=float, default=0.01,
                   help="half-width of the gap around 0 excluded for sign/step and "
                        "for the composite rows (default 0.01)")
    p.add_argument("--eval-points", type=int, default=8192, help="dense evaluation grid size")
    p.add_argument("--minimax-grid", type=int, default=4096,
                   help="minimum Lawson grid size (default 4096)")
    p.add_argument("--max-iter", type=int, default=500, help="Lawson iteration cap")
    p.add_argument("--tol", type=float, default=1e-12, help="Lawson relative stopping tolerance")
    p.add_argument("--compare-cap", type=int, default=255,
                   help="largest degree fitted for the same-depth minimax comparison rows")
    p.add_argument("--composite-k", type=int, default=4,
                   help="number of CKK compositions reported for sign/step/relu (default 4)")
    p.add_argument("--no-polish", action="store_true",
                   help="pure Lawson, without the Remez exchange polish")
    p.add_argument("--handoff", type=float, default=1e-2,
                   help="Lawson duality gap at which the exchange polish takes over (default 1e-2)")
    p.add_argument("--json", metavar="OUT.json", help="write coefficients and metrics")
    p.add_argument("--twin", metavar="OUT.py", help="write a numpy evaluation snippet")
    p.add_argument("--emit", help="method whose series --twin emits (interp/ls/wls/minimax, "
                                  "or composite:K); default interp")
    p.add_argument("--selftest", action="store_true", help="run the self tests and exit")
    return p


def main(argv=None):
    args = build_parser().parse_args(argv)
    if args.selftest:
        return selftest(args)
    if not args.expr and not args.function:
        sys.exit("error: give a preset function or --expr")
    if args.degree is None and args.depth is None:
        sys.exit("error: give --degree or --depth")
    run(args)
    return 0


if __name__ == "__main__":
    sys.exit(main())
